<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Composition with Red, Blue and Yellow (1930) — Piet Mondrian</title>
<meta name="description" content="Piet Mondrian's 1930 Composition with Red, Blue and Yellow: a De Stijl canvas of primary-colour blocks that became a reference for modern graphic design and architecture.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&display=swap" rel="stylesheet">
<style>
:root{
  --red:#e30613;
  --blue:#1441c8;
  --yellow:#f7d117;
  --black:#111111;
  --white:#ffffff;
  --line:8px;
  --maxw:1100px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:"Archivo",system-ui,sans-serif;
  background:var(--white);
  color:var(--black);
  line-height:1.55;
}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 24px}
a{color:inherit}

/* header */
header{
  border-bottom:var(--line) solid var(--black);
  background:var(--white);
}
header .wrap{
  display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding-top:18px;padding-bottom:18px;flex-wrap:wrap;
}
.brand{font-weight:900;letter-spacing:.02em;font-size:15px;text-transform:uppercase}
.brand span{
  display:inline-block;width:12px;height:12px;background:var(--red);
  margin-right:8px;vertical-align:-1px;
}
nav{display:flex;gap:22px;font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:.06em}
nav a{text-decoration:none;border-bottom:3px solid transparent;padding-bottom:2px}
nav a:hover{border-bottom-color:var(--black)}

/* hero */
.hero{
  display:grid;grid-template-columns:minmax(0,420px) 1fr;
  min-height:72vh;align-items:stretch;
}
.hero .canvas{
  background:var(--white);
  border-right:var(--line) solid var(--black);
  display:flex;
}
#scene{width:100%;height:100%;display:block}
.hero .text{
  padding:56px 48px;
  display:flex;flex-direction:column;justify-content:center;gap:28px;
}
.kicker{
  font-weight:900;font-size:13px;text-transform:uppercase;letter-spacing:.12em;
  display:flex;align-items:center;gap:10px;
}
.kicker::before{content:"";width:18px;height:18px;background:var(--yellow);display:inline-block}
h1{
  font-size:clamp(34px,4.6vw,58px);
  font-weight:900;line-height:1.04;text-transform:uppercase;letter-spacing:-.01em;
}
h1 em{font-style:normal}
h1 .c-red{color:var(--red)}
h1 .c-blue{color:var(--blue)}
h1 .c-yellow{color:#b8960a}
.meta{display:flex;flex-wrap:wrap;gap:12px}
.meta div{
  border:3px solid var(--black);padding:8px 14px;font-size:13px;font-weight:700;
  text-transform:uppercase;letter-spacing:.04em;
}
.meta div b{display:block;font-size:11px;font-weight:500;letter-spacing:.08em;opacity:.65;margin-bottom:2px;text-transform:uppercase}
.lead{font-size:clamp(17px,1.6vw,20px);max-width:46ch}

/* sections */
section.block{border-top:var(--line) solid var(--black);padding:64px 0}
section.block .wrap{display:grid;grid-template-columns:minmax(0,300px) 1fr;gap:48px}
section.block h2{
  font-size:clamp(22px,2.4vw,32px);font-weight:900;text-transform:uppercase;
  letter-spacing:.02em;line-height:1.2;
}
h2::after{content:"";display:block;width:64px;height:10px;margin-top:14px}
#movement h2::after{background:var(--blue)}
#principles h2::after{background:var(--yellow)}
#matters h2::after{background:var(--red)}
section.block p{font-size:17px;max-width:62ch}
section.block p + p{margin-top:14px}

/* principles chips */
.chips{display:flex;flex-wrap:wrap;gap:12px;margin-top:24px}
.chip{
  border:3px solid var(--black);padding:10px 16px;font-weight:700;font-size:14px;
  display:flex;align-items:center;gap:10px;text-transform:uppercase;letter-spacing:.04em;
}
.chip i{width:20px;height:20px;display:inline-block;border:2px solid var(--black)}
.chip.red i{background:var(--red)}
.chip.blue i{background:var(--blue)}

